"use client"

import * as React from "react"
import { Toast as ToastPrimitive } from "@base-ui/react/toast"
import { cva, type VariantProps } from "class-variance-authority"
import { Icon } from "@iconify/react"

import { cn } from "@/lib/utils"

// Control Room Toast: alarm-console event.
// Console plate with the popover glow; destructive events carry a red
// signal edge and red glow, like an unacknowledged CRIT row.

const ToastProvider = ToastPrimitive.Provider

const ToastViewport = React.forwardRef<
  HTMLDivElement,
  ToastPrimitive.Viewport.Props
>(({ className, ...props }, ref) => (
  <ToastPrimitive.Portal>
    <ToastPrimitive.Viewport
      ref={ref}
      className={cn(
        "fixed top-0 z-[100] flex max-h-screen w-full flex-col-reverse p-4 sm:bottom-0 sm:right-0 sm:top-auto sm:flex-col md:max-w-[26.25rem]",
        className
      )}
      {...props}
    />
  </ToastPrimitive.Portal>
))
ToastViewport.displayName = "ToastViewport"

const toastVariants = cva(
  [
    "group pointer-events-auto relative flex w-full items-center justify-between space-x-4 overflow-hidden p-4",
    "rounded-md border border-border",
    "[box-shadow:var(--shadow-popover)]",
    "transition-all data-swiping:translate-x-[var(--toast-swipe-movement-x)] data-swiping:transition-none data-ending-style:opacity-80 data-ending-style:translate-x-full data-starting-style:-translate-y-full sm:data-starting-style:translate-y-full",
  ].join(" "),
  {
    variants: {
      variant: {
        default: "bg-popover text-popover-foreground",
        destructive:
          "destructive bg-popover text-destructive border-destructive/40 " +
          "[box-shadow:0_0_0_0.0625rem_oklch(0.6_0.23_27/0.3),0_0.75rem_1.75rem_oklch(0_0_0/0.55),0_0_1.125rem_oklch(0.6_0.23_27/0.2)]",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

const Toast = React.forwardRef<
  HTMLDivElement,
  ToastPrimitive.Root.Props & VariantProps<typeof toastVariants>
>(({ className, variant, swipeDirection = "right", ...props }, ref) => {
  return (
    <ToastPrimitive.Root
      ref={ref}
      swipeDirection={swipeDirection}
      className={cn(toastVariants({ variant }), className)}
      {...props}
    />
  )
})
Toast.displayName = "Toast"

const ToastAction = React.forwardRef<
  HTMLButtonElement,
  ToastPrimitive.Action.Props
>(({ className, ...props }, ref) => (
  <ToastPrimitive.Action
    ref={ref}
    className={cn(
      "inline-flex h-7 shrink-0 items-center justify-center rounded-sm px-2.5",
      "border border-border bg-secondary",
      "text-xs font-semibold uppercase tracking-wider transition-colors",
      "hover:bg-accent hover:text-primary",
      "focus:outline-none focus:ring-2 focus:ring-ring/60",
      "disabled:pointer-events-none disabled:opacity-50",
      "group-[.destructive]:border-destructive/40 group-[.destructive]:hover:bg-destructive/15 group-[.destructive]:hover:text-destructive",
      className
    )}
    {...props}
  />
))
ToastAction.displayName = "ToastAction"

const ToastClose = React.forwardRef<
  HTMLButtonElement,
  ToastPrimitive.Close.Props
>(({ className, ...props }, ref) => (
  <ToastPrimitive.Close
    ref={ref}
    className={cn(
      "absolute right-2 top-2 rounded-xs p-1 text-muted-foreground opacity-0",
      "transition-opacity hover:text-destructive",
      "focus:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring/60",
      "group-hover:opacity-100",
      className
    )}
    toast-close=""
    {...props}
  >
    <Icon icon="tabler:x" className="size-4" />
  </ToastPrimitive.Close>
))
ToastClose.displayName = "ToastClose"

const ToastTitle = React.forwardRef<
  HTMLHeadingElement,
  ToastPrimitive.Title.Props
>(({ className, ...props }, ref) => (
  <ToastPrimitive.Title
    ref={ref}
    className={cn(
      "text-xs font-semibold uppercase tracking-widest",
      className
    )}
    {...props}
  />
))
ToastTitle.displayName = "ToastTitle"

const ToastDescription = React.forwardRef<
  HTMLParagraphElement,
  ToastPrimitive.Description.Props
>(({ className, ...props }, ref) => (
  <ToastPrimitive.Description
    ref={ref}
    className={cn("text-xs leading-relaxed opacity-90", className)}
    {...props}
  />
))
ToastDescription.displayName = "ToastDescription"

type ToastProps = React.ComponentPropsWithoutRef<typeof Toast>

type ToastActionElement = React.ReactElement<typeof ToastAction>

export {
  type ToastProps,
  type ToastActionElement,
  ToastProvider,
  ToastViewport,
  Toast,
  ToastTitle,
  ToastDescription,
  ToastClose,
  ToastAction,
}
